from pathlib import Path
root=Path(__file__).resolve().parent.parent
def label(t): return f'<p class="demo-label">{t}</p>'
def btn(t,url): return f'<a class="demo-btn" href="{url}">{t} <span aria-hidden="true">↗</span></a>'
def page(name,theme,brand,sub,nav,body,extra=''):
    links=''.join(f'<a href="{h}">{t}</a>' for h,t in nav[:-1])+f'<a class="nav-action" href="{nav[-1][0]}">{nav[-1][1]}</a>'
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{brand.replace('<span>','').replace('</span>','')} — JNIT Design Concept</title><meta name="description" content="An interactive fictional website concept designed by JNIT to demonstrate premium web experiences."><link rel="icon" href="assets/favicon.ico"><link rel="stylesheet" href="demo-premium.css?v=20260926"></head><body class="{theme}"><div class="demo-ribbon"><a href="web-development.html#demos">← JNIT design showcase</a><span>FICTIONAL BRAND / INTERACTIVE CONCEPT</span><a href="quote.html?service=website">Build something like this ↗</a></div><header class="demo-nav-new"><a class="demo-brand" href="#main-content">{brand}<small>{sub}</small></a><button class="demo-menu" type="button" aria-expanded="false" aria-controls="demo-navigation">Menu</button><nav class="demo-nav-links" id="demo-navigation" aria-label="Demo navigation">{links}</nav></header><main id="main-content">{body}</main><footer class="demo-foot"><div><span class="demo-brand">{brand}</span><p>A fictional brand created to demonstrate JNIT’s website design capabilities. Photography is AI-generated concept imagery. Content, services and pricing are illustrative. No bookings, purchases or enquiries are sent by this demo.</p></div><div><p>Like the direction?</p><a href="quote.html?service=website">Let’s create something for your business ↗</a><br><a href="web-development.html#demos">Explore more JNIT concepts ↗</a></div></footer><script src="demo-premium.js"></script>{extra}</body></html>'''
    (root/name).write_text(html,encoding='utf-8')
def form(kind,title,fields,button):
    return f'<form class="demo-form" data-demo-form="{kind}"><h3>{title}</h3>{fields}<button class="demo-btn" type="submit">{button} <span aria-hidden="true">↗</span></button><p class="demo-disclosure">Try the interaction. This is a fictional design concept; no real booking or enquiry will be sent.</p><p class="demo-result" role="status" tabindex="-1" hidden></p></form>'
def select(label_,name,options):
    return f'<label>{label_}<select name="{name}" required>'+''.join(f'<option>{x}</option>' for x in options)+'</select></label>'

iron=f'''<section class="iron-hero"><div class="iron-hero-copy">{label('Architecture in the making')}<h1>Built to<br><em>belong.</em></h1><p>Considered homes. Honest materials. Spaces shaped around the way you live.</p>{btn('Tell us about your project','#project-brief')}</div><figure><img src="images/demos/construction.webp" width="1536" height="1024" alt="AI concept of a contemporary home with warm stone and a garden courtyard" fetchpriority="high"><figcaption><span>THE COURTYARD HOUSE</span><span>RESIDENTIAL CONCEPT ↗</span></figcaption></figure></section><div class="iron-band"><span>NEW HOMES</span><span>THOUGHTFUL RENOVATIONS</span><span>CONSIDERED INTERIORS</span><span>FROM PLAN TO PLACE</span></div><section class="demo-section" id="approach"><div class="demo-heading"><div>{label('Our point of view')}<h2>A home should feel right.<br>Long before the final detail.</h2></div><p>Good building begins with listening. We bring the same care to the first conversation, the site and every finishing touch.</p></div><div class="iron-project" id="projects"><div><img src="images/demos/construction.webp" width="1536" height="1024" alt="Courtyard House architectural concept" loading="lazy"><p class="demo-caption">SELECTED DESIGN STUDY / CONCEPT IMAGERY</p></div><div>{label('The Courtyard House')}<h3>Quiet confidence.<br>Open to the landscape.</h3><p>Natural stone, deep shade and generous openings. A residential concept that puts light, privacy and everyday life in balance.</p><dl><div><dt>Direction</dt><dd>Contemporary residential</dd></div><div><dt>Materials</dt><dd>Stone · timber · glass</dd></div><div><dt>Approach</dt><dd>Indoor / outdoor living</dd></div></dl>{btn('Start a conversation','#project-brief')}</div></div></section><section class="demo-section iron-services" id="services"><div class="demo-split"><div>{label('What we do')}<h2>From an idea<br>to a place to call home.</h2></div><div><details open><summary>New homes <span>+</span></summary><p>From early planning to the final handover, a coordinated build shaped around your site, your priorities and your vision.</p></details><details><summary>Renovations <span>+</span></summary><p>Reimagine the spaces you already know. Thoughtful alterations, considered extensions and material choices that bring a home together.</p></details><details><summary>Interior completion <span>+</span></summary><p>Joinery, finishes and the details you touch every day, coordinated as part of a complete project.</p></details></div></div></section>'''
iron+=f'<section class="demo-section" id="project-brief"><div class="demo-split"><div>{label("Let’s begin")}<h2>Your plans.<br>Our first conversation.</h2><p>Share where you are in the process. A short brief helps establish the right next step.</p></div>'+form('construction','A place to start',select('What are you planning?','project',['A new home','A renovation','An interior project'])+select('Where are you in the process?','stage',['Exploring an idea','Designs in progress','Plans ready to build']),'Preview my brief')+'</div></section>'
page('demo-construction.html','iron','IRON<span>/</span>WOOD','BUILDING WITH INTENTION',[('#approach','Our approach'),('#projects','Selected work'),('#services','Services'),('#project-brief','Start a project')],iron)

still=f'''<section class="still-hero"><div>{label('Space to slow down')}<h1>Come back<br>to <em>yourself.</em></h1><p>Unhurried rituals. Thoughtful touch. A little space between you and the everyday.</p>{btn('Find your moment','#rituals')}</div><figure><img src="images/demos/wellness.webp" width="1536" height="1024" alt="AI concept of a sunlit wellness room with ivory linen and a stone arch" fetchpriority="high"><span class="still-seal">A little time.<strong>Just you.</strong></span></figure></section><section class="still-philosophy" id="philosophy">{label('The art of doing a little less')}<h2>We believe in quieter mornings,<br>deeper breaths, and care that<br>meets you where you are.</h2></section><section class="demo-section" id="rituals"><div class="demo-heading"><div>{label('Our rituals')}<h2>Choose what<br>you need today.</h2></div><p>Small, considered experiences with space to arrive, settle and leave feeling more like yourself.</p></div><div class="ritual-grid"><article class="ritual-card"><span>60 MINUTES / SAMPLE RITUAL</span><h3>The grounding massage</h3><p>Slow, intentional movements and warm botanical oils. An invitation to soften and settle.</p><a href="#visit" data-ritual="Grounding massage">Explore this ritual ↗</a></article><article class="ritual-card"><span>45 MINUTES / SAMPLE RITUAL</span><h3>The skin reset</h3><p>A considered facial ritual with gentle cleansing, restorative touch and an unhurried finish.</p><a href="#visit" data-ritual="Skin reset">Explore this ritual ↗</a></article><article class="ritual-card"><span>90 MINUTES / SAMPLE RITUAL</span><h3>The slow afternoon</h3><p>A longer pause. Body and face rituals brought together, with tea and time at either end.</p><a href="#visit" data-ritual="Slow afternoon">Explore this ritual ↗</a></article></div></section>'''
still+=f'<section class="demo-section still-book" id="visit"><div class="demo-split"><div>{label("Make a little space")}<h2>Your next hour<br>can feel different.</h2><p>A simple booking experience, designed to feel as calm as the visit itself. Choose a ritual and explore a sample appointment.</p></div>'+form('wellness','A moment for you',select('Your ritual','ritual',['Grounding massage','Skin reset','Slow afternoon'])+select('Your preferred moment','time',['Morning · 09:00','Midday · 12:00','Afternoon · 15:00']),'Preview my visit')+'</div></section>'
page('demo-wellness.html','still','still.','A STUDIO FOR YOURSELF',[('#philosophy','Our philosophy'),('#rituals','The rituals'),('#visit','Plan your visit')],still)

dishes=[('Coal-roasted beetroot','Goat’s curd · smoked almond · sorrel','R135'),('Linefish over embers','Spring peas · preserved lemon · herb oil','R285'),('Karoo lamb','Aubergine · cultured cream · rosemary','R325'),('Dark chocolate crémeux','Olive oil · sea salt · roasted hazelnut','R125')]
