terra+=f'<section class="demo-section" id="reserve"><div class="demo-split"><div>{label("An evening to look forward to")}<h2>There’s a place<br>at the table.</h2><p>Try the reservation experience. A few simple choices, a clear confirmation, and room for a little anticipation.</p></div>'+form('restaurant','Plan an evening',select('Your table','guests',['2','3','4','5','6'])+select('Your sitting','sitting',['Lunch · 12:30','Dinner · 18:00','Dinner · 19:30']),'Preview reservation')+'</div></section>'
