aura=f'''<section class="aura-shell"><div class="aura-copy">{label('Objects of light / Interactive edition')}<h1>Light, made<br><em>personal.</em></h1><p>A quiet object with a different character in every room. Meet Sol, our sculptural lighting concept.</p><div class="aura-controls"><div class="aura-control-label"><span>Choose your finish</span><strong id="finish-name" aria-live="polite">Warm ivory</strong></div><div class="aura-swatches" role="group" aria-label="Lamp finish"><button class="aura-swatch" data-finish="ivory" aria-label="Warm ivory finish" aria-pressed="true"></button><button class="aura-swatch" data-finish="graphite" aria-label="Deep graphite finish" aria-pressed="false"></button><button class="aura-swatch" data-finish="clay" aria-label="Terracotta finish" aria-pressed="false"></button></div><label class="aura-control-label" for="light-level"><span>Set the mood</span><output id="light-value" for="light-level">65%</output></label><input type="range" id="light-level" min="0" max="100" value="65" aria-label="Lamp brightness"><div class="aura-tools"><button type="button" id="rotate-toggle" aria-pressed="false">Auto-rotate</button><button type="button" id="reset-view">Reset view</button><button type="button" id="scene-mode" aria-pressed="false">Evening light</button></div></div></div><div class="aura-scene-wrap" id="product-view"><div class="aura-fallback" id="lamp-fallback" aria-hidden="true"><div class="css-lamp"><span></span></div></div><canvas class="aura-canvas" id="aura-canvas" tabindex="0" aria-label="Interactive 3D lamp. Drag horizontally or use left and right arrow keys to rotate."></canvas><p class="aura-scene-note" id="scene-help">DRAG TO EXPLORE · ARROW KEYS TO ROTATE</p></div></section><div class="aura-specs"><span><strong>Sol / Table light</strong>A fictional product concept</span><span><strong>Three considered finishes</strong>Ivory · Graphite · Terracotta</span><span><strong>Change the atmosphere</strong>Live light and material controls</span><span><strong>Made to be explored</strong>Interactive 3D by JNIT</span></div><section class="demo-section" id="details"><div class="demo-heading"><div>{label('Form. Feeling. Function.')}<h2>An object worth<br>getting to know.</h2></div><p>Let people explore before they enquire. Product storytelling becomes an experience they can take part in.</p></div><div class="aura-details"><article><h3>See every side.</h3><p>A real-time 3D model invites a closer look. Rotate with a mouse, touch or keyboard.</p></article><article><h3>Make it yours.</h3><p>Compare material finishes and change the lighting to see how a product’s character shifts.</p></article><article><h3>Keep it effortless.</h3><p>A focused interface, responsive layout and a lightweight scene that respects reduced-motion preferences.</p></article></div></section><section class="demo-section" id="enquire" style="padding-top:0">{btn('Create an interactive experience with JNIT','quote.html?service=website')}<p class="demo-disclosure" style="margin-top:22px">This is a JNIT capability demonstration. Aura and Sol are fictional; no product is offered for sale.</p></section>'''
page('demo-3d.html','aura','AURA','OBJECTS OF LIGHT',[('#product-view','Explore Sol'),('#details','The details'),('#enquire','Made for your brand')],aura,'<script type="module" src="demo-3d.js"></script>')
